-- O.S. abertas (PIMS) da Produção Agrícola + recomendação de produtos da fertirrigação.
--
-- É o SELECT que o sistema já usa, sem mudar nada dele, com as colunas novas da planilha
-- "Logística Fertirrigação" no fim: CD_COMPO, DE_COMPO, QT_RECURSO, CD_UNIMED e RESERVA.
-- Os componentes (PA_MATRIZ_OS + COMPONEN) entram por outer join (+) e só nas operações 509 e
-- 524: nas outras O.S. essas colunas vêm vazias e o resultado continua uma linha por talhão.
-- Nas de fertirrigação vem uma linha por talhão × componente; a importação junta tudo na mesma
-- O.S. e a página Fertirrigação lê a vazão (componente em M3), a recomendação de produtos e os
-- tratos (CCUSTO_TRATOS).
--
-- Exporte o resultado em Excel e importe na tela de O.S., como hoje.

SELECT ODE.CD_UPNIVEL1 AS SECAO,
       UP2.CD_UPNIVEL2 AS SETOR,
       UP3.CD_UPNIVEL3 AS TALHAO,
       OHE.NO_OS,
       OHE.CD_OPERACAO AS OPERACAO,
       OP.DE_OPERACAO AS DESCRICAO_OPERACAO,
       OHE.CD_CCUSTO AS CCUSTO,
       CC.DE_CCUSTO AS CCUSTO_TRATOS,
       TO_CHAR(OHE.DT_EMISSAO_OS,'DD/MM/YYYY') AS DT_ABERTURA_OS,
       COMP.CD_COMPO,
       COMP.DE_COMPO,
       MAT_OS.QT_RECURSO,
       COMP.CD_UNIMED,
       CASE WHEN OHE.CD_OPERACAO IN (509,524) THEN OHE.DE_OBSERVACAO END AS RESERVA
FROM PA_OS_HE OHE, PA_OS_DE ODE, UPNIVEL2 UP2, UPNIVEL3 UP3, CCUSTOS CC, OPERACOES OP, PA_MATRIZ_OS MAT_OS, COMPONEN COMP
WHERE OHE.NO_OS = ODE.NO_OS
  AND OHE.NO_OS_ASSOC = OHE.NO_OS
  AND OHE.INSTANCIA = ODE.INSTANCIA
  AND OHE.INSTANCIA IN (201,204,401,402)
  AND OHE.CD_CCUSTO = CC.CD_CCUSTO
  AND ODE.CD_UPNIVEL2 = UP2.CD_UPNIVEL2
  AND ODE.CD_UPNIVEL3 = UP3.CD_UPNIVEL3
  AND ODE.CD_SAFRA = UP3.CD_SAFRA
  AND ODE.CD_UPNIVEL1 = UP3.CD_UPNIVEL1
  AND OHE.CD_OPERACAO = OP.CD_OPERACAO
  AND MAT_OS.NO_OS(+) = CASE WHEN OHE.CD_OPERACAO IN (509,524) THEN ODE.NO_OS END
  AND MAT_OS.INSTANCIA(+) = ODE.INSTANCIA
  AND MAT_OS.CD_UPNIVEL2(+) = ODE.CD_UPNIVEL2
  AND COMP.CD_COMPO(+) = MAT_OS.CD_RECURSO
  AND OHE.CD_OPERACAO IN (1,2,3,5,6,7,9,10,11,13,14,17,18,22,25,26,28,31,34,37,38,40,43,46,49,50,51,54,55,56,57,58,59,60,61,62,64,65,67,73,75,76,87,88,90,91,94,97,98,99,100,101,102,103,104,105,106,107,108,109,110,112,113,114,115,116,117,118,135,136,137,138,139,140,141,142,143,144,145,200,201,250,251,252,253,254,255,256,258,260,261,262,263,264,265,267,300,301,302,303,304,306,307,308,309,310,313,314,315,316,317,318,319,320,321,322,323,324,325,326,327,328,329,330,331,332,333,334,335,336,338,339,340,341,342,343,345,346,347,348,349,350,351,352,353,354,355,356,357,358,359,360,361,362,363,364,365,366,367,368,369,370,371,372,373,374,375,376,377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395,396,397,398,399,400,401,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,426,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,443,444,445,446,447,448,449,450,451,452,453,454,455,456,457,458,459,460,461,462,463,464,465,466,467,468,469,470,471,472,473,474,475,476,477,478,479,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,495,496,497,498,499,500,501,502,503,504,505,506,507,508,509,510,511,512,513,514,515,516,517,518,519,520,521,522,523,524,525,526,527,528,529,530,531,532,533,534,535,536,537,538,539,540,541,542,543,544,545,546,547,548,549,550,551,552,553,600,601,602,603,605,691,692,693,694,695,696,700,701,702,703,704,705,706,707,708,709,710,711,712,713,714,715,716,717,718,719,720,721,722,723,724,725,726,727,728,729,730,731,732,733,734,735,736,737,738,739,740,741,742,743,744,745,746,747,748,749,750,751,752,753,754,755,756,757,758,759,760,761,762,763,764,765,766,767,768,769,770,771,772,773,774,775,776,777,778,779,780,781,782,783,784,785,786,787,788,789,790,791,792,793,794,795,796,797,798,799,800,801,802,803,804,805,806,807,808,809,810,811,812,813,814,815,818,819,820,822,823,824,825,826,827,828,829,830,831,832,833,834,835,836,837,838,839,840,841,843,844,845,847,848,849,851,852,853,854,855,856,857