  AND OHE.DT_EMISSAO_OS >= TO_DATE('01/01/2026','DD/MM/YYYY')
  AND OHE.FG_SITUACAO = 'A'
GROUP BY ODE.CD_UPNIVEL1,OHE.NO_OS,UP2.CD_UPNIVEL2,UP3.CD_UPNIVEL3,OHE.CD_OPERACAO,OP.DE_OPERACAO,OHE.CD_CCUSTO,CC.DE_CCUSTO,OHE.DT_EMISSAO_OS,
         COMP.CD_COMPO,COMP.DE_COMPO,MAT_OS.QT_RECURSO,COMP.CD_UNIMED,OHE.DE_OBSERVACAO
ORDER BY UP2.CD_UPNIVEL2,OHE.CD_OPERACAO,UP3.CD_UPNIVEL3,OHE.DT_EMISSAO_OS DESC
